using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using SaucyMVC.Data;
namespace SaucyMVC.Controllers; public class MenuController:Controller { readonly SaucyDbContext _db; public MenuController(SaucyDbContext db)=>_db=db; public async Task<IActionResult> Index(string? category){var q=_db.MenuItems.Where(x=>x.IsAvailable).AsQueryable();if(!string.IsNullOrWhiteSpace(category))q=q.Where(x=>x.Category==category);ViewBag.Categories=await _db.MenuItems.Where(x=>x.IsAvailable).Select(x=>x.Category).Distinct().OrderBy(x=>x).ToListAsync();ViewBag.SelectedCategory=category;ViewBag.Sauces=await _db.SauceOptions.OrderBy(x=>x.DisplayOrder).ThenBy(x=>x.Name).ToListAsync();return View(await q.OrderBy(x=>x.Category).ThenBy(x=>x.Name).ToListAsync());} }
